import java.io.*;

public class Perturbed3 {
    static boolean DEBUG_FLAG = false;

    static long calculate(long n, long m) {
        if (n > m) {
            long t = n;
            n = m;
            m = t;
        }
        long prod = n * m;
        if (n <= 3 && m <= 3) {
            if (n == 1 || m == 1) return 0;
            if (n == 2 && m == 2) return 0;
            if (n == 2 && m == 3) return 4;
            if (n == 3 && m == 3) return 8;
            return 0;
        }
        if (n == 1) {
            m %= 6;
            if (m == 4) m = 2;
            else if (m == 5) m = 1;
            return prod - m;
        }
        if (n == 2) {
            if (m == 3 || m == 7) m = 2;
            else m = 0;
            return prod - m;
        }
        return prod - prod % 2;
    }

    static class FastScanner {
        private DataInputStream in;
        private byte[] buffer;
        private int bufferPointer;
        private int bytesRead;

        public FastScanner() {
            in = new DataInputStream(System.in);
            buffer = new byte[1 << 16];
            bufferPointer = bytesRead = 0;
        }

        private int read() throws IOException {
            if (bufferPointer >= bytesRead) {
                bytesRead = in.read(buffer, 0, buffer.length);
                if (bytesRead == -1) return -1;
                bufferPointer = 0;
            }
            return buffer[bufferPointer++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c <= ' ' && c != -1) c = read();
            if (c == -1) throw new IOException("EOF");
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int value = 0;
            while (c > ' ' && c != -1) {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }
    }

    public static void main(String[] args) throws IOException {
        if (args.length > 0 && args[0].equalsIgnoreCase("d")) DEBUG_FLAG = true;
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        long start = System.nanoTime();
        int n = fs.nextInt();
        int m = fs.nextInt();
        out.println(calculate(n, m));
        long end = System.nanoTime();

        debug("\nTime: " + (end - start) / 1e6 + " \n\n");
        out.close();
    }

    static void debug(String s) {
        if (DEBUG_FLAG) System.out.print(s);
    }
}
